def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """

    from datetime import datetime, timedelta, tzinfo
    import pytz

    if tz is not None:
        tz = pytz.timezone(tz)

    seconds = nanoseconds // 1_000_000_000
    microseconds = nanoseconds % 1_000_000_000

    if seconds < 0:
        raise ValueError("nanoseconds must be non-negative")

    if tz is None:
        return datetime.fromtimestamp(seconds, tz) + timedelta(microseconds=microseconds)
    else:
        return tz.fromutc((datetime.utcfromtimestamp(seconds) + timedelta(microseconds=microseconds)).replace(tzinfo=pytz.UTC))

