def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None, hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    if mode not in [None, "READ", "WRITE"]:
        raise ValueError("Invalid mode. Must be 'READ', 'WRITE', or None.")
    if not isinstance(bookmarks, (list, tuple)) and bookmarks is not None:
        raise ValueError("Bookmarks must be an iterable or None.")
    if not isinstance(metadata, dict) and metadata is not None:
        raise ValueError("Metadata must be a dictionary or None.")
    if not isinstance(timeout, (int, float)) and timeout is not None:
        raise ValueError("Timeout must be a number or None.")
    if not isinstance(db, str) and db is not None:
        raise ValueError("Database name must be a string or None.")
    if not isinstance(imp_user, str) and imp_user is not None:
        raise ValueError("Impersonated user must be a string or None.")
    if not isinstance(dehydration_hooks, dict) and dehydration_hooks is not None:
        raise ValueError("Dehydration hooks must be a dictionary or None.")
    if not isinstance(hydration_hooks, dict) and hydration_hooks is not None:
        raise ValueError("Hydration hooks must be a dictionary or None.")

    message = {"BEGIN": {}}
    if mode:
        message["BEGIN"]["mode"] = mode
    if bookmarks:
        message["BEGIN"]["bookmarks"] = bookmarks
    if metadata:
        message["BEGIN"]["metadata"] = metadata
    if timeout:
        message["BEGIN"]["timeout"] = timeout
    if db:
        message["BEGIN"]["db"] = db
    if imp_user:
        message["BEGIN"]["imp_user"] = imp_user
    if dehydration_hooks:
        message["BEGIN"]["dehydration_hooks"] = dehydration_hooks
    if hydration_hooks:
        message["BEGIN"]["hydration_hooks"] = hydration_hooks

    response = self.send_message(message, **handlers)
    return response

def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, rounding half to even (bankers' rounding).

    :param n: The number to round.
    :return: The rounded number.
    """
    if n % 1 == 0.5 or n % 1 == -0.5:
        return int(n) + int(n < 0)
    return round(n)

def round_half_to_even(n):
    """
    Round a number to the nearest even number when the fractional part is exactly 0.5.

    :param n: The number to round.
    :return: The rounded number.
    """
    if isinstance(n, int):
        return n

    fractional_part = n % 1
    if fractional_part == 0.5:
        return int(n) + 1 if n > 0 else int(n) - 1
    else:
        return round(n)

