def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    if not name or not fields:
        raise ValueError("Name and fields must be provided")

    # Create the namespace for the new class
    namespace = {}
    for field in fields:
        if field in namespace:
            raise ValueError(f"Field name duplicated: {field}")
        namespace[field] = field

    # Create the Point subclass dynamically
    Point = type(name, (Point,), namespace)

    # Add SRID mapping functionality if available
    if srid_map:
        Point.srid_map = {field: srid for field, srid in srid_map.items()}

