def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """

    try:
        BaseClass = type_
    except TypeError:
        BaseClass = object

    class MetaClass(_ValidationMeta, BaseClass.__class__):
        pass

    class Point(BaseClass, metaclass=MetaClass):
        """Dynamic Point subclass derived from BaseClass with specified fields
        and srid_map."""
        __slots__ = fields

        @classmethod
        def from_srid(cls, srid):
            if srid not in srid_map:
                raise ValueError(f"SRID {srid} not found in srid_map")
            return srid_map[srid]

    return Point

