from functools import wraps
from collections import OrderedDict

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache_info = {
            'hits': 0,
            'misses': 0,
            'maxsize': maxsize,
            'currsize': 0
        }

        cache = OrderedDict()
        lock = threading.Lock() if maxsize > 1 else None

        def cache_threshold():
            return max(1, maxsize // 10)

        def expired(key):
            return timer() - cache[key][1] > ttl

        def make_key(args, kwds, typed=typed):
            try:
                return (args, frozenset(kwds.items())) if typed else (args, frozenset(kwds.items()))
            except TypeError:
                # uncachable as the key is unhashable
                return None

        def wrapper(*args, **kwds):
            nonlocal cache, cache_info
            key = make_key(args, kwds)
            if key is None:
                return func(*args, **kwds)

            with lock or dummy_contextmanager():
                entry = cache.get(key)
                if entry is not None and not expired(key):
                    cache.move_to_end(key)
                    cache_info['hits'] += 1
                    return entry[0]
                else:
                    cache_info['misses'] += 1
                    result = func(*args, **kwds)
                    cache[key] = (result, timer())
                    cache_info['currsize'] += 1
                    while cache_info['currsize'] > cache_info['maxsize']:
                        oldest_key = next(iter(cache))
                        cache_info['currsize'] -= 1
                        cache.pop(oldest_key)
                    return result

        def cache_clear():
            nonlocal cache, cache_info
            with lock or dummy_contextmanager():
                cache.clear()
                cache_info['currsize'] = 0

        def cache_info():
            return cache_info.copy()

        wrapper.cache_clear = cache_clear
        wrapper.cache_info = cache_info
        return wrapper

    return decorator

class dummy_contextmanager(object):
    def __init__(self):
        self.gen = ()
    def __enter__(self):
        return next(self.gen)
    def __exit__(self, *args, **kwds):
        try:
            next(self.gen)
        except StopIteration:
            pass
        return False
