def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    if maxsize < 1:
        raise ValueError('maxsize must be at least 1')

    from collections import OrderedDict, Counter

    def decorator(func):
        instance_count = Counter()
        instance_fifo = OrderedDict()

        class Node:
            def __init__(self, key, value, freq=1):
                self.key = key
                self.value = value
                self.freq = freq

        def getitem(key):
            try:
                node = instance_fifo[key]
            except KeyError:
                raise KeyError(f"{func.__name__}({key}) not in cache")

            # Update frequency and move to the end of the FIFO list
            instance_count[node.freq] -= 1
            if instance_count[node.freq] == 0:
                del instance_count[node.freq]
            node.freq += 1
            instance_fifo.move_to_end(key)
            instance_count[node.freq] += 1
            return node.value

        def setitem(key, value):
            if key in instance_fifo:
                node = instance_fifo[key]
                instance_fifo.move_to_end(key)
            else:
                if len(instance_fifo) >= maxsize:
                    # Remove the least frequently used item
                    lfu = instance_count[min(instance_count)]
                    lfu_key = next(k for k, v in instance_fifo.items() if v == lfu)
                    del instance_fifo[lfu_key]
                    del instance_count[lfu]
                node = Node(key, value)
                setitem(key, node)  # Recursive call to set the node

            # Add or update the node
            instance_fifo[key] = node
            if node.freq not in instance_count:
                instance_count[node.freq] = 1
            else:
                instance_count[node.freq] += 1

        def _clear():
            instance_count.clear()
            instance_fifo.clear()

        def wraps(func):
            def wrapper(*args, **kwargs):
                key = (func.__name__, args, tuple(kwargs.items()) if typed else None)
                try:
                    result = getitem(key)
                except KeyError:
                    result = func(*args, **kwargs)
                    setitem(key, result)
                return result

            _clear()

            def put(*args, **kwargs):
                key = (func.__name__, args, tuple(kwargs.items()) if typed else None)
                yield functools.partial(setitem, key)

            def forget(*args, **kwargs):
                key = (func.__name__, args, tuple(kwargs.items()) if typed else None)
                setitem(key, None)

            def clear():
                _clear()

            wrapper.put = put
            wrapper.forget = forget
            wrapper.clear = clear

            return _update_wrapper(wrapper, func)

        return wraps

    return decorator

