def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    bases = []
    for cls in classes:
        if cls not in bases:
            bases.append(cls)
            bases.extend(cls.__bases__)
    return bases

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    # Create a dictionary to track the minimum base class for each class
    min_base = {}
    for cls in classes:
        min_base[cls] = cls

    # Iterate through the classes to find the minimal base
    for cls in classes:
        for base in cls.__bases__:
            if base in min_base and min_base[base] is not cls:
                min_base[cls] = min_base[base]
                cls = min_base[cls]
                # Update the base dict for all subclasses of cls
                subclasses = [sub for sub in min_base if min_base[sub] is cls]
                for sub in subclasses:
                    min_base[sub] = min_base[cls]

    return list(min_base.values())

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    def isSuperclass(cls, other):
        try:
            other.__bases__
        except AttributeError:
            return False
        return cls in other.__bases__ or any(isSuperclass(cls, b) for b in other.__bases__)

    result = []
    for cls in classes:
        if not any(isSuperclass(cls, result_cls) for result_cls in result):
            result.append(cls)

    return result

def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent
    """
    if not classes:
        return []

    # Create a dictionary to keep track of the minimum index for each base class
    index_map = {cls: i for i, cls in enumerate(classes)}

    # Initialize the minimal bases list with the first class
    minimal = [classes[0]]

    # Iterate over the rest of the classes and remove duplicates
    for cls in classes[1:]:
        if index_map[cls] < index_map[minimal[-1]]:
            minimal.pop()
        minimal.append(cls)

    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    ordered_classes = []
    for cls in classes:
        if not any(cls is ancestor or cls in ancestor.__mro__ for ancestor in ordered_classes):
            ordered_classes.append(cls)
    return ordered_classes

