def namesAndDescriptions(self, all=False): # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""

    descriptions = {}
    for attr_name in dir(self):
        attr = getattr(self, attr_name)
        if inspect.isroutine(attr) or not inspect.ispublic(attr_name):
            continue
        docstring = attr.__doc__
        if docstring:
            descriptions[attr_name] = docstring.strip()
        else:
            descriptions[attr_name] = "No description available"

    if all:
        return descriptions

    return {name: desc for name, desc in descriptions.items() if desc.strip()}

def namesAndDescriptions(self, all=False): # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""

    if not hasattr(self, '_interface'):
        raise AttributeError("Interface not set")

    descriptions = {}
    for attr_name in dir(self):
        attr_value = getattr(self, attr_name)
        if callable(attr_value) or not attr_name.startswith('__'):
            descriptions[attr_name] = attr_value.__doc__

    if not all:
        # Filter out private attributes and methods
        descriptions = {k: v for k, v in descriptions.items() if not k.startswith('_')}

    return descriptions

