       add keyword argument *level*.
    """
    if level == 0:
        return {}

    if isinstance(d1, dict) and isinstance(d2, dict):
        diff_dict = {}
        keys = set(d1).union(set(d2))
        for key in keys:
            if key in d1 and key not in d2:
                diff_dict[key] = d1[key]
            elif key in both d1 and d2:
                sub_diff = difference(d1[key], d2[key], level=level - 1)
                if sub_diff:
                    diff_dict[key] = sub_diff
        return diff_dict
    else:
        return d1 if d1 != d2 else None
