def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """

    default_schema = {}
    if app.spec.manifest is not None:
        for resource in app.spec.manifest:
            resource_type = resource['apiVersion'] + '.' + resource['kind']
            if resource_type not in app.observer_schemas:
                default_schema[resource_type] = {}
                if 'spec' in resource:
                    default_schema[resource_type]['spec'] = {}
                    for field, value in resource['spec'].items():
                        if isinstance(value, dict):
                            default_schema[resource_type]['spec'][field] = generate_default_observer_schema(app)
                        else:
                            default_schema[resource_type]['spec'][field] = value
                else:
                    default_schema[resource_type]['spec'] = {}
                if 'status' in resource:
                    default_schema[resource_type]['status'] = {}
                    for field, value in resource['status'].items():
                        if isinstance(value, dict):
                            default_schema[resource_type]['status'][field] = generate_default_observer_schema(app)
                        else:
                            default_schema[resource_type]['status'][field] = value
                else:
                    default_schema[resource_type]['status'] = {}

                app.observer_schemas[resource_type] = default_schema[resource_type]

    return default_schema

