def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    default_observer_schema = {}

    for resource in app.spec.manifest:
        resource_name = resource["apiVersion"].split("/")[1] + "/" + resource["kind"]
        if resource_name not in default_observer_schema:
            default_observer_schema[resource_name] = {
                "type": "object",
                "properties": {},
                "required": []
            }

        # Add fields based on resource manifest
        for key, value in resource["spec"].items():
            if isinstance(value, dict):
                default_observer_schema[resource_name]["properties"][key] = generate_default_schema(value)
                if key not in default_observer_schema[resource_name]["required"]:
                    default_observer_schema[resource_name]["required"].append(key)
            elif isinstance(value, list):
                item_schema = generate_default_schema(value[0]) if value else {}
                default_observer_schema[resource_name]["properties"][key] = {
                    "type": "array",
                    "items": item_schema
                }
                if key not in default_observer_schema[resource_name]["required"]:
                    default_observer_schema[resource_name]["required"].append(key)
            else:
                default_observer_schema[resource_name]["properties"][key] = {
                    "type": "string"
                }
                if key not in default_observer_schema[resource_name]["required"]:
                    default_observer_schema[resource_name]["required"].append(key)

    return default_observer_schema

def generate_default_schema(data):
    """Generate a default schema based on the given data."""
    if isinstance(data, dict):
        return {
            "type": "object",
            "properties": {k: generate_default_schema(v) for k, v in data.items()},
            "required": list(data.keys())
        }
    elif isinstance(data, list):
        return {
            "type": "array",
            "items": generate_default_schema(data[0]) if data else {}
        }
    else:
        return {
            "type": "string"
        }
