def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[str, Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[str, Any]], List[Sequence[Any]]]]:
    out_params = []
    formatted_sql = sql

    for params in many_params:
        placeholders = []
        if isinstance(params, Mapping):
            if self.SQLParams.in_style == 'named':
                formatted_sql = formatted_sql.replace('?', '{}')
                placeholders = [f'{{{param}}}' for param in params]
            else:
                raise ValueError("Cannot use named parameters with an ordinal style")
        elif isinstance(params, Sequence):
            if self.SQLParams.in_style == 'ordinal':
                ordered_placeholders = []
                for i, _ in enumerate(params):
                    placeholder = f'?{i + 1}'
                    placeholders.append(placeholder)
                formatted_sql = formatted_sql.replace('?', '{}')
                placeholders = placeholders[::-1]
            else:
                raise ValueError("Cannot use ordinal parameters with a named style")
        else:
            raise ValueError("Invalid parameters type")

        out_params.append({placeholder: value for placeholder, value in zip(placeholders, params)})

    return formatted_sql, out_params
