def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import os
    import zipfile

    package_data = {}

    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            for file_info in zip_ref.infolist():
                file_name = file_info.filename
                if file_name.endswith('.xml'):
                    xml_name = os.path.splitext(file_name)[0]
                    xml_content = zip_ref.read(file_name)
                    if xml_name in package_data:
                        package_data[xml_name].append(xml_content)
                    else:
                        package_data[xml_name] = [xml_content]
    except zipfile.BadZipFile as e:
        print(f"Error opening zip file: {e}")
        return {}
    except Exception as e:
        print(f"An error occurred: {e}")
        return {}

    return package_data
