def absorb(args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, tuple) and len(arg) == 3:
            op1, op, op2 = arg
            if op == '&':
                if isinstance(op1, tuple) and len(op1) == 3 and op1[1] == '|':
                    if op1[0] == op2:
                        new_args.append(op1[0])
                    elif op2 in op1[2]:
                        new_args.append(op1)
                elif isinstance(op2, tuple) and len(op2) == 3 and op2[1] == '|':
                    if op2[0] == op1:
                        new_args.append(op2[0])
                    elif op1 in op2[2]:
                        new_args.append(op2)
            elif op == '|':
                if isinstance(op1, tuple) and len(op1) == 3 and op1[1] == '&':
                    if op1[0] == op2:
                        new_args.append(op1[0])
                    elif op2 in op1[2]:
                        new_args.append(op1)
                elif isinstance(op2, tuple) and len(op2) == 3 and op2[1] == '&':
                    if op2[0] == op1:
                        new_args.append(op2[0])
                    elif op1 in op2[2]:
                        new_args.append(op2)
        else:
            new_args.append(arg)
    return new_args

