def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    def absorb_or(expr1, expr2):
        if expr1 == expr2:
            return expr1
        else:
            return f"({expr1} | {expr2})"

    def absorb_and(expr1, expr2):
        if expr1 == expr2:
            return expr1
        else:
            return f"({expr1} & {expr2})"

    def neg_absorb_and(expr1, expr2):
        neg_expr1 = f"~{expr1}"
        return absorb_and(expr1, absorb_or(neg_expr1, expr2))

    def neg_absorb_or(expr1, expr2):
        neg_expr1 = f"~{expr1}"
        return absorb_or(expr1, absorb_and(neg_expr1, expr2))

    def apply_absorption(expr):
        if expr.count('&') > expr.count('|'):
            parts = expr.split('&')
            return absorb_and(parts[0], apply_absorption(absorb_or(*parts[1:])))
        elif expr.count '|' > expr.count('&'):
            parts = expr.split('|')
            return absorb_or(parts[0], apply_absorption(absorb_and(*parts[1:])))
        else:
            return expr

    def apply_neg_absorption(expr):
        if expr.count('&') > expr.count('|'):
            parts = expr.split('&')
            return neg_absorb_and(parts[0], apply_neg_absorption(neg_absorb_or(*parts[1:])))
        elif expr.count '|' > expr.count('&'):
            parts = expr.split('|')
            return neg_absorb_or(parts[0], apply_neg_absorption(neg_absorb_and(*parts[1:])))
        else:
            return expr

    def process_expression(expr):
        absorbed_expr = apply_absorption(expr)
        neg_absorbed_expr = apply_neg_absorption(absorbed_expr)
        return neg_absorbed_expr

    return [process_expression(expr) for expr in args]
