    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        # Apply absorption laws
        if isinstance(arg, tuple):
            new_arg = tuple(self.absorb(exp) for exp in arg)
        elif isinstance(arg, str):
