def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expr in args:
        if isinstance(expr, tuple) and len(expr) == 2:
            operator, subexpr = expr
            if operator == 'and':
                if isinstance(subexpr, tuple) and len(subexpr) == 2:
                    sub_operator, sub_subexpr = subexpr
                    if sub_operator == 'or':
                        result.append(sub_subexpr[0] if sub_subexpr[0] == sub_subexpr[1] else expr)
                    elif sub_operator == 'and':
                        result.append(sub_subexpr)
            elif operator == 'or':
                if isinstance(subexpr, tuple) and len(subexpr) == 2:
                    sub_operator, sub_subexpr = subexpr
                    if sub_operator == 'and':
                        result.append(sub_subexpr[0] if sub_subexpr[0] == sub_subexpr[1] else expr)
                    elif sub_operator == 'or':
                        result.append(sub_subexpr)
        else:
            result.append(expr)
