def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def simplify_expression(expr):
        if expr.is_binary:
            left, operator, right = expr.left, expr.operator, expr.right
            if operator == 'and':
                if left == right:
                    return left
                if left == expr(not right):
                    return expr(right)
                if right == expr(not left):
                    return expr(left)
            elif operator == 'or':
                if left == right:
                    return left
                if left == expr(not right):
                    return expr(not right)
                if right == expr(not left):
                    return expr(not left)
        return expr

    def expr(a):
        if isinstance(a, int):
            return a
        if isinstance(a, str):
            if a == '0':
                return False
            if a == '1':
                return True
            if a.startswith('not '):
                return expr(a[4:]) == False
        return a

    return [simplify_expression(expr(arg)) for arg in args]

