from collections.abc import Mapping
from typing import List, Tuple

def deep_merge_nodes(nodes: List[Tuple[MappingNode, MappingNode]]) -> List[Tuple[MappingNode, MappingNode]]:
    merged_dict = {}

    for key_node, value_node in nodes:
        if key_node not in merged_dict:
            merged_dict[key_node] = value_node
        else:
            if not isinstance(merged_dict[key_node], MappingNode):
                merged_dict[key_node] = value_node
            else:
                if not isinstance(value_node, MappingNode):
                    merged_dict[key_node] = value_node
                else:
                    merged_dict[key_node].value = merge_mapping_nodes(merged_dict[key_node].value, value_node.value)

    result = [(key_node, merged_dict[key_node]) for key_node, value_node in merged_dict.items()]
    return result

def merge_mapping_nodes(lhs_dict: dict, rhs_dict: dict) -> dict:
    combined_dict = {**lhs_dict, **rhs_dict}
    for key, value in combined_dict.items():
        if key in lhs_dict and key in rhs_dict and isinstance(lhs_dict[key], MappingNode) and isinstance(rhs_dict[key], MappingNode):
            combined_dict[key] = merge_mapping_nodes(lhs_dict[key].value, rhs_dict[key].value)
    return combined_dict
