def size_to_bytes(size: str) -> int:
    suffixes = {
        'B': 1,
        'K': 1024,
        'M': 1024**2,
        'G': 1024**3,
        'T': 1024**4,
        'P': 1024**5,
        'E': 1024**6,
        'Z': 1024**7,
        'Y': 1024**8
    }

    if not size:
        raise ValueError("Empty size string")

    unit = size[-1].upper()
    numeric_part = size[:-1]

    if unit not in suffixes:
        raise ValueError("Invalid unit: {}".format(unit))

    try:
        numeric_part = float(numeric_part)
    except ValueError:
        raise ValueError("Non-numeric part: {}".format(numeric_part))

    return int(numeric_part * suffixes[unit])

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    units = {'B': 1, 'K': 1024, 'M': 1024**2, 'G': 1024**3, 'T': 1024**4, 'P': 1024**5, 'E': 1024**6, 'Z': 1024**7, 'Y': 1024**8}

    if not size:
        return 0

    number, unit = size[:-1], size[-1]

    try:
        number = float(number)
    except ValueError:
        return 0

    if unit in units:
        return int(number * units[unit])
    else:
        return int(number)

