def vertex3tuple(vertices):
    '''return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::


        polygon with vertices ABCD
        Will return
        (D, A, B), (A, B, C), (B, C, D), (C, D, A) -> returns lists of vertices
        #A    B    C    D  -> of vertices
    '''
    try:
        return _vertex3tuple_cache[vertices]
    except AttributeError:
        pass
    except KeyError:
        _vertex3tuple_cache = {}
    if len(vertices) < 4:
        raise ValueError("Input list must contain at least 4 vertices to form a polygon.")
    vertex3tuple_lists = []
    for i in range(len(vertices)):
        vertex3tuple_lists.append([vertices[i-1], vertices[i], vertices[(i+1)%len(vertices)]])
    _vertex3tuple_cache[vertices] = vertex3tuple_lists
    return vertex3tuple_lists
