    """Return all subclasses of a class, recursively"""
    seen = set([cls])
    queue = set([cls])

    while queue:
        c = queue.pop()
        for sc in c.__subclasses__():
            if sc not in seen:
                seen.add(sc)
                queue.add(sc)

    return seen
