        regex = r'"([^"\\]*(?:\\.[^"\\]*)*)"|\'([^\'\\]*(?:\\.[^\'\\]*)*)\'|[^\s\\\'"][^\\]*(?:\\.[^\\ ]*)*'
    else:
        regex = r'"([^"\\]*(?:\\.[^"\\]*)*)"|([^"\'\\s][^\\\' \n]*)'

