import os
import subprocess
from pathlib import Path
from typing import Optional, Union

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[Path, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not os.path.exists(archive_path):
        raise ValueError("Archive path does not exist: {}".format(archive_path))

    if filename:
        extract_path = os.path.join(tmp_path, filename)
    else:
        extract_path = tmp_path

    if not os.path.exists(extract_path):
        os.makedirs(extract_path)

    if archive_path.endswith('.tar.gz'):
        subprocess.run(['tar', '-xzf', archive_path], cwd=extract_path)
    elif archive_path.endswith('.tar.bz2'):
        subprocess.run(['tar', '-xjf', archive_path], cwd=extract_path)
    elif archive_path.endswith('.zip'):
        subprocess.run(['unzip', archive_path], cwd=extract_path)
    else:
        raise ValueError("Unsupported archive type: {}".format(archive_path))

    return "file://{}".format(extract_path)
