    """ Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma. """
    result = subprocess.run(['git', 'status', '--ignored'], capture_output=True, text=True)
    if result.returncode != 0:
        raise Exception("Git command failed: " + result.stderr)

    ignored_files = [line.split()[1] for line in result.stdout.split('\n') if line.split()[1] in ignored]
    ignored_files.sort()

    return ','.join(ignored_files)
