def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    frequency = frequency.strip()
    if not frequency or not frequency[-1].isalpha():
        raise ValueError("Invalid frequency format")

    num = ""
    unit = ""
    for char in frequency:
        if char.isdigit():
            num += char
        else:
            unit += char
            break

    if not num.isdigit() or not unit.strip():
        raise ValueError("Invalid frequency format")

    num = int(num)
    unit = unit.strip()

    if unit == "second":
        return datetime.timedelta(seconds=num)
    elif unit == "minute":
        return datetime.timedelta(minutes=num)
    elif unit == "hour":
        return datetime.timedelta(hours=num)
    elif unit == "day":
        return datetime.timedelta(days=num)
    elif unit == "week":
        return datetime.timedelta(weeks=num)
    elif unit == "month":
        return datetime.timedelta(days=num * 30)
    elif unit == "year":
        return datetime.timedelta(days=num * 365)
    else:
        raise ValueError("Invalid time unit")

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    try:
        num, unit = frequency.split()
        num = int(num)
        if unit == "seconds":
            result = datetime.timedelta(seconds=num)
        elif unit == "minutes":
            result = datetime.timedelta(minutes=num)
        elif unit == "hours":
            result = datetime.timedelta(hours=num)
        elif unit == "days":
            result = datetime.timedelta(days=num)
        elif unit == "weeks":
            result = datetime.timedelta(weeks=num)
        elif unit == "months":
            days_in_month = 30  # Approximation
            result = datetime.timedelta(days=num * days_in_month)
        elif unit == "years":
            days_in_year = 365  # Approximation
            result = datetime.timedelta(days=num * days_in_year)
        else:
            raise ValueError(f"Unknown unit: {unit}")
        return result
    except (ValueError, AttributeError):
        raise ValueError(f"Cannot parse frequency: {frequency}")

