from typing import Optional, Set
from rdflib import Graph, URIRef, Node

def find_roots(graph: Graph, prop: URIRef, roots: Optional[Set[Node]] = None) -> Set[Node]:
    if roots is None:
        roots = set()

    for s, p, o in graph.triples((None, prop, None)):
        if p != prop:
            continue

        parents = list(graph.subjects(pred=p, obj=s))
        if not parents:
            roots.add(s)
        else:
            roots.update(parents)

    return roots

