    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import os

    def load_config(filename):
        try:
            if filename.endswith('.toml'):
                with open(filename, 'r') as fd:
                    config = toml.load(fd)
            elif filename.endswith('.json'):
                with open(filename, 'r') as fd:
                    config = json.load(fd)
            else:
                raise ValueError(f"Unsupported config file format: {filename}")

            if resolve_env:
                config = recursively_expand_env_vars(config)

            return config
        except Exception as e:
            log.error(f"Error loading config from {filename}: {e}")
            return None, [logging.LogRecord(log.name, logging.ERROR, filename, 0, str(e), [], None)]

    def recursively_expand_env_vars(config):
        if isinstance(config, dict):
            return {k: recursively_expand_env_vars(v) for k, v in config.items()}
        elif isinstance(config, list):
            return [recursively_expand_env_vars(v) for v in config]
        elif isinstance(config, str):
            return os.path.expandvars(config)
        else:
            return config

    log = logging.getLogger(__name__)
    config_dict = {}
    log_records = []

    for filename in config_filenames:
        new_config, new_log_records = load_config(filename)
        config_dict[filename] = new_config
        log_records.extend(new_log_records)

    return config_dict, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import toml
    import yaml
    import os
    import sys
    import logging.config

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            if not os.path.isfile(filename):
                raise FileNotFoundError(f"File {filename} not found.")

            with open(filename, 'r') as fd:
                raw_config = fd.read()

            if filename.endswith('.toml'):
                config = toml.loads(raw_config)
            elif filename.endswith('.yaml') or filename.endswith('.yml'):
                config = yaml.safe_load(raw_config)
            else:
                raise ValueError(f"Unsupported configuration file format: {filename}")

            if resolve_env:
                import os, re
                for key, value in config.items():
                    if isinstance(value, str) and re.match(r'^\$\{.*\}$', value):
                        env_key = value.strip('{}')
                        config[key] = os.getenv(env_key)

            config_dict[filename] = config
        except Exception as e:
            log_record = logging.LogRecord(logging.ERROR, e.__class__.__name__, filename, None, (str(e),), None)
            log_records.append(log_record)

    return config_dict, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.

    :param config_filenames: Sequence of configuration filenames to load.
    :type config_filenames: Iterable[str]
    :param overrides: Dictionary of configuration values to override in loaded configurations.
    :type overrides: Dict[str, Any], optional
    :param resolve_env: Boolean indicating whether to resolve environment variables in configuration values.
    :type resolve_env: bool, optional
    :return: Tuple of dictionary of configuration filename to configuration and sequence of LogRecord instances.
    :rtype: Tuple[Dict[str, Any], Iterable[logging.LogRecord]]
    """
    if overrides is None:
        overrides = {}

    configs = {}
    errors = []

    for filename in config_filenames:
        try:
            with open(filename) as fd:
                raw_config = fd.read()
                config = yaml.safe_load(raw_config)
                if resolve_env:
                    config = {k: os.path.expandvars(v) if isinstance(v, str) else v for k, v in config.items()}
                for key, value in overrides.items():
                    if key in config:
                        config[key] = value
                configs[filename] = config
        except FileNotFoundError:
            errors.append(logging.LogRecord(name='load_configurations', level=logging.ERROR, pathname=filename, lineno=0, msg='Configuration file not found.', args=(), exc_info=None))
        except Exception as e:
            errors.append(logging.LogRecord(name='load_configurations', level=logging.ERROR, pathname=filename, lineno=0, msg=f'Error loading configuration file: {e}', args=(), exc_info=None))

    return configs, errors

