    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid(f"{candidate} does not claim to provide {iface}")

    method_errors = []
    attribute_errors = []

    for name in iface.names():
        attr = getattr(candidate, name, None)
        if attr is None:
            if iface.getSpecification(name).isAttribute():
                attribute_errors.append(f"{candidate} does not define attribute {name}")
            elif iface.getSpecification(name).isMethod():
                method_errors.append(f"{candidate} does not define method {name}")
            continue

        if isinstance(attr, classmethod) or isinstance(attr, staticmethod):
            attr = attr.__func__

        if not callable(attr):
            if iface.getSpecification(name).isAttribute():
                attribute_errors.append(f"{name} in {candidate} is not callable")
            else:
                method_errors.append(f"{name} in {candidate} is not callable")
            continue

        if isinstance(attr, MethodType):
            if not isFunctionOrMethodSignatureMatch(attr, iface.getSpecification(name)):
                if iface.getSpecification(name).isAttribute():
                    attribute_errors.append(f"{name} in {candidate} has incorrect signature")
                else:
                    method_errors.append(f"{name} in {candidate} has incorrect signature")

        if iface.getSpecification(name).isAttribute():
            if not isinstance(attr, attr.getInterface().getType()):
                attribute_errors.append(f"{name} in {candidate} has incorrect type")

    if method_errors or attribute_errors:
        errors = method_errors + attribute_errors
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("Multiple errors: " + ", ".join(errors))

    return True

def isFunctionOrMethodSignatureMatch(func, method_spec):
    func_type = type(func)
    method_type = method_spec.getInterface().getSignature()

    if func_type is not method_type:
        return False

    return True

