def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid(f"Candidate does not claim to provide interface {iface}")

    implemented_methods = set(iface.namesAll(1))
    implemented_attributes = set(iface.namesAll(2))
    defined_methods = set(candidate.__dict__.keys())
    defined_attributes = set(candidate.__dict__.keys())

    missing_methods = implemented_methods - defined_methods
    missing_attributes = implemented_attributes - defined_attributes

    method_errors = []
    for method in missing_methods:
        method_def = getattr(candidate.__class__, method, None)
        if method_def is not None and hasattr(method_def, '__isabstractmethod__'):
            method_errors.append(f"Method {method} from interface {iface} is abstract and not overridden")
        else:
            method_errors.append(f"Method {method} from interface {iface} is not defined")

    attribute_errors = []
    for attribute in missing_attributes:
        attribute_def = getattr(candidate, attribute, None)
        if attribute_def is None:
            attribute_errors.append(f"Attribute {attribute} from interface {iface} is not defined")

    if method_errors or attribute_errors:
        error_message = ""
        if method_errors:
            error_message += "Methods errors: " + ", ".join(method_errors)
        if attribute_errors:
            error_message += "Attribute errors: " + ", ".join(attribute_errors)

        if len(method_errors + attribute_errors) == 1:
            raise zope.interface.Invalid(error_message)
        else:
            raise zope.interface.Invalid(error_message)

    return True
