def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid("Candidate does not provide interface")

    method_errors = {}
    attribute_errors = {}

    for name, method in iface.__dict__.items():
        if callable(method):
            if name not in candidate.__dict__:
                method_errors[name] = f"Method {name} not defined"
            else:
                candidate_method = candidate.__dict__[name]
                if not callable(candidate_method):
                    method_errors[name] = f"Method {name} is not callable"

    for name, _ in iface.__dict__.items():
        if name not in candidate.__dict__:
            attribute_errors[name] = f"Attribute {name} not defined"

    errors = list(method_errors.values()) + list(attribute_errors.values())
    if errors:
        if len(errors) == 1:
            raise errors[0]
        else:
            raise zope.interface.Invalid("Multiple errors: " + ", ".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    for attr in iface.__dict__:
        if callable(iface.__dict__[attr]):
            if attr not in candidate.__dict__ or not callable(candidate.__dict__[attr]):
                return False
            candidate_attr = candidate.__dict__[attr]
            iface_attr = iface.__dict__[attr]
            if tentative:
                return True
            if not _are_callable_signatures_compatible(iface_attr, candidate_attr):
                return False
    return True

def _are_callable_signatures_compatible(func1, func2):
    """
    Check if the signatures of two callable objects are compatible.
    """
    sig1 = inspect.signature(func1)
    sig2 = inspect.signature(func2)
    return sig1 == sig2

