def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Check if explicit metaclass is provided
    if explicit_mc is not None:
        return explicit_mc

    # Iterate over bases to find explicit metaclass declaration
    for base in bases:
        # Check for __metaclass__ attribute in older Python versions
        if hasattr(base, '__metaclass__'):
            return base.__metaclass__

    # Use the first base class's metaclass if available
    for base in bases:
        # Retrieve the inferred class definition for the base
        for baseobj in base.infer():
            if isinstance(baseobj, ClassDef):
                # Return the meta class of the first valid base class
                return baseobj.type()

    # If no metaclass is found, return None
    return None
