def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    def linkify_url(url):
        return f'<a href="{url}" target="_blank">{url}</a>'

    def linkify_text(text):
        return re.sub(r'(https?://\S+)', lambda m: linkify_url(m.group(0)), text)

    # Check for URLs and add target="_blank" attribute
    linkified_text = re.sub(r'(https?://\S+)', lambda m: linkify_url(m.group(0)), text)

    # Check for file references and add <a> tag with /browse/ prefix
    def maybe_add_link(match):
        path = match.group(0)
        if path.startswith('/'):
            path = re.sub(r'^/', '', path)
            return f'<a href="/browse/{path}" target="_blank">{path}</a>'
        return path

    linkified_text = re.sub(r'/[^/]+', maybe_add_link, linkified_text)

    return linkified_text
