import re
import os

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    # Regular expression to find URLs and file references
    link_regex = r'(https?://[^\s]+|/[^ \s/]+|[^ \s/]+:)'

    def linkify_url(url):
        if url.startswith('http'):
            return url
        elif url.startswith('/'):
            url = os.path.relpath(url, start=os.getcwd())
        else:
            return None

        if os.path.exists(url):
            return f'<a href="{url}" target="_blank">{url}</a>'
        else:
            return None

    def linkify_textual_link(text):
        if link_regex.match(text):
            return text
        else:
            return f'<a href="{text}" target="_blank">{text}</a>'

    def replace_link(match):
        url_or_text = match.group(0)
        if '@' in url_or_text or '.' in url_or_text:
            return linkify_textual_link(url_or_text)
        else:
            return linkify_url(url_or_text)

    return re.sub(link_regex, replace_link, text)
