def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    import re

    def linkify_and_decorate(match):
        url = match.group(0)
        # Basic URL link
        if re.match(r'https?://[\w.]+', url):
            return f'<a href="{url}" target="_blank">{url}</a>'
        # Email link
        elif re.match(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b', url):
            return f'<a href="mailto:{url}" target="_blank">{url}</a>'
        # Phone number link
        elif re.match(r'\+?\d[\d -]{8,14}\d', url):
            return f'<a href="tel:{url}" target="_blank">{url}</a>'
        # Hash link
        elif re.match(r'#\w+', url):
            return f'<a href="{url}" target="_blank">{url}</a>'
        # File path link
        elif re.match(r'[\w/.-]+', url):
            return f'<a href="/browse/{url}" target="_blank">{url}</a>'
        # Default, no linkification
        else:
            return url

    LinkRegex = r'https?://[\w.]+|mailto:\w+@\w+\.\w+|\+?\d[\d -]{8,14}\d|#\w+|[\w/.-]+'
    return re.sub(LinkRegex, linkify_and_decorate, text)

