from typing import Dict
import json
from xml.etree import ElementTree as ET
from urllib.parse import urlparse

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Attempt to parse as JSON
        data = json.loads(document)
    except json.JSONDecodeError:
        # If JSON fails, parse as XRD
        root = ET.fromstring(document)
        data = {}
        for child in root:
            if child.tag.endswith('semi-qualified-name:ActivityStreamsType') and child.text == 'Person':
                for prop in child:
                    if prop.tag.endswith('semi-qualified-name:ActivitiesIOHandle'):
                        data['handle'] = prop.text
                    elif prop.tag.endswith('semi-qualified-name:.URI'):
                        data['url'] = prop.text
                    elif prop.tag.endswith('semi-qualified-name:PreferredUsername'):
                        data['nickname'] = prop.text
                    elif prop.tag.endswith('semi-qualified-name:APIdoc'):
                        data['ap_id'] = urlparse(prop.text).netloc
                    elif prop.tag.endswith('semi-qualified-name:pods'):
                        data['pods'] = [pod.text for pod in prop.findall('Pod')]
                    elif prop.tag.endswith('semi-qualified-name:DL'):
                        data['has_blog'] = 'true' if prop.text.lower() == 'true' else 'false'
        data['hcard_url'] = root.find('{http://well-known.webfinger.net/xrd}Link[@rel="http://microformats.org/profile/hcard"]').attrib['href']
    return data
