def parse_xrd(document: str) -> Dict:
    parser = XMLParser()
    tree = ET.parse(StringIO(document), parser)
    root = tree.getroot()
    hcard_url = get_hcard_url(root)
    return {"hcard_url": hcard_url}

def get_hcard_url(root: ElementTree) -> str:
    for link in root.findall('{urn:xrd:1.0}Link[@rel="http://microformats.org/profile/hcard"]'):
        href = link.get("{http://www.w3.org/XML/1998/namespace}base") + link.get("href")
        return href
    return None

