def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        import json
        parsed = json.loads(document)
        if "links" in parsed and any(link.get("rel") == "http://microformats.org/profile/hcard" for link in parsed["links"]):
            hcard_url = next((link["href"] for link in parsed["links"] if link["rel"] == "http://microformats.org/profile/hcard"), None)
