        hcard_url = root.find(".//{http://microformats.org/profile/hcard}link[@rel='alternate'][@type='text/html']").attrib["href"]
        return {"hcard_url": hcard_url}
    except (ET.ParseError, AttributeError):
        pass

    return {}
