def list_of_file_names(settings_dirs, spec_option):
    """Return a list of file names from the given settings directories based on the specified option.

    Args:
        settings_dirs (list of str): List of directory paths containing configuration files.
        spec_option (str): Specification option to filter the files.

    Returns:
        list of str: List of fully qualified file names matching the specified option.
    """
    try:
        file_list = []
        for dir_path in settings_dirs:
            for root, _, files in os.walk(dir_path):
                for file in files:
                    if file.endswith(f".{spec_option}"):
                        file_list.append(os.path.join(root, file))
        return sorted(file_list)
    except (OSError, TypeError):
        return []
