    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise errors.InvalidSpecError('Unable to resolve default for non-Option type')

        # if there is a default set in the spec, add it to the defaults dict
        if arg.spec and isinstance(arg.spec.default, SpecDefaultValue):
            defaults[arg.name] = arg.spec.default.value

        # if there is a default source set, use it to resolve the default
        if arg.default_source:
            try:
                value = arg.default_source.resolve()
                defaults[arg.name] = value
            except Exception as e:
                raise errors.DefaultSourceError(f'Unable to resolve default for {arg.name}: {e}')

        # if we have a dict option, build the defaults for its scheme.
        # if any defaults exist, use them.
        if isinstance(arg, DictOption):
            if arg.scheme:
                b = arg.scheme.get_spec_defaults()
                if b:
                    defaults[arg.name] = b
    return defaults
