            nested_args[arg_name] = arg_value
        elif arg_name.startswith('--custom'):
            custom_args[arg_name] = arg_value

    # Combine control and nested args into final dictionaries
    final_control_args = control_args.copy()
    final_nested_args = nested_args.copy()

    # Add custom args to nested args if they are not already present
    for key, value in custom_args.items():
        if key not in nested_args:
            nested_args[key] = value

    return final_control_args, final_nested_args

