def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active
    workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down
        directly to Ansible.
    """
    if verbose is None:
        verbose = "-v"
    elif verbose == "debug":
        verbose = "-vvvvv"
    else:
        try:
            verbose = "-v" * int(verbose)
        except ValueError:
            raise ValueError("Invalid verbosity level: %s" % verbose)

    command = ["ansible-playbook", verbose, playbook_path]

    if extra_vars:
        for var, val in extra_vars.items():
            command.append("-e")
            command.append("%s=%s" % (var, val))

    if ansible_args:
        command.extend([str(k) for k, v in ansible_args.items()])
        command.extend([str(v) for k, v in ansible_args.items()])

    logger.debug("Executing Ansible command: %s", " ".join(command))
    p = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    stdout, stderr = p.communicate()

    if p.returncode != 0:
        error_message = (f"Error executing ansible-playbook: {stderr.decode('utf-8')}"
                          if stderr else "Ansible reported an error.")
        raise RuntimeError(error_message)

    return stdout.decode('utf-8')

